//@ run-pass
// Acceptance test 3 for compiler prerequisite #3 (trait-bounded generic method dispatch).
// Tests multiple trait methods, multiple type instantiations, and generic->generic chaining.
// Expected output: 8, 5, 9, then "multi_call PASS"

struct Pair {
    x: i64,
    y: i64,
}

trait R {
    fn radd(self, o: Self) -> Self
    fn rsub(self, o: Self) -> Self
}

impl R for i64 {
    fn radd(self, o: Self) -> Self { self + o }
    fn rsub(self, o: Self) -> Self { self - o }
}

impl R for Pair {
    fn radd(self, o: Self) -> Self {
        Pair { x: self.x + o.x, y: self.y + o.y }
    }
    fn rsub(self, o: Self) -> Self {
        Pair { x: self.x - o.x, y: self.y - o.y }
    }
}

// First bounded function: calls two different trait methods
fn compute<F: R>(a: F, b: F) -> F {
    a.radd(b)
}

// Second bounded function: calls another bounded function internally
fn combine<F: R>(a: F, b: F, c: F) -> F {
    let intermediate = compute::<F>(a, b)
    intermediate.rsub(c)
}

fn main() with IO {
    let i1 = 10
    let i2 = 2
    let i3 = 1

    let p1 = Pair { x: 4, y: 5 }
    let p2 = Pair { x: 2, y: 2 }
    let p3 = Pair { x: 1, y: 1 }

    let res_i = combine::<i64>(i1, i2, i3)
    println(res_i)

    let res_p = combine::<Pair>(p1, p2, p3)
    println(res_p.x)
    println(res_p.y)

    println("multi_call PASS")
}

//@ run-pass
//@ description: &t.N / &!t.N on a tuple element that is a ONE-FIELD struct must not crash
//@ expect-stdout-contains: tuple_one_slot_struct_borrow: PASS
//
// tuple_borrow_elem_resolve() (fix for &t.0 / &!t.0 generally) resolves a tuple element's
// address and type, but every element wider than one slot is copied inline by the tuple
// constructor while a ONE-slot struct element is stored as the struct's value in rax --
// a pointer to its data, not the cell holding a pointer. Taking that cell's address (as
// every other element kind wants) yields a pointer to a pointer; the first read through
// it dereferences garbage and segfaults.
//
// Scope: locally built tuples only. A one-field struct inside a tuple RETURNED from a
// function is its own, separate, older, pre-existing bug -- the pointer such an element
// holds is into the callee's dead frame, so it is garbage after the next call whether or
// not any borrow is involved (`let a = mk_one(); other_call(); a.0.n` reads garbage with
// zero borrows in play). That bug is not fixed here; this test avoids it by only
// constructing the one-field-struct tuples in `main`'s own frame.
//
// Scope: local variables only (x86). Global tuple variables have a separate, pre-existing
// issue with tuple-typed globals unrelated to element width, so a one-field struct in a
// global tuple is not covered here either.

struct One { n: i64 }

fn one_n(b: &One) -> i64 { b.n }
fn set_n(b: &!One, v: i64) with Mut { b.n = v }
fn iv(x: &i64) -> i64 { *x }
fn noise(a: i64) -> i64 { a * 3 }

fn main() -> i64 with IO, Mut {
    var bad: i64 = 0

    // read, first position
    let a = (One { n: 7 }, 2)
    if one_n(&a.0) != 7 { bad = bad + 1 }

    // read, second position
    let b = (2, One { n: 9 })
    if one_n(&b.1) != 9 { bad = bad + 1 }

    // mutate through &!t.0 changes the tuple itself
    var u = (One { n: 0 }, 2)
    set_n(&!u.0, 42)
    if u.0.n != 42 { bad = bad + 1 }

    // borrow survives other calls (the tuple is local, not returned)
    let z = noise(5)
    if one_n(&a.0) != 7 { bad = bad + 1 }

    // chained field access through the borrow, after another call
    let q = (One { n: 11 }, 22)
    let z2 = noise(6)
    if one_n(&q.0) != 11 { bad = bad + 1 }
    if iv(&q.1) != 22 { bad = bad + 1 }

    if bad == 0 {
        println("tuple_one_slot_struct_borrow: PASS")
        return 0
    }
    print("tuple_one_slot_struct_borrow: FAIL, wrong/crashed = ")
    println(bad)
    return 1
}

//@ run-pass
//@ expect-stdout: type-hash 3-level PASS
// Regression for the i64 type-hash overflow on 3-level pointer nesting
// (closed in 2523ee2f4 by composite-type interning in lean_single.sio).
//
// Pre-fix: ref_hash_make compounded the inner hash by *256 per level while
// the inner still carried the 2^50 band, so &Option<Box<Struct>> wrapped
// mod 2^64 and corrupted the struct hash — field access reported
// "unknown field" and shapes collided.
//
// Post-fix: composite inners are interned (CT_INNER_HASH[4096]) and only
// a small surrogate id is multiplied, keeping the encoded hash inside
// [2^50, 2^51) at arbitrary depth.
//
// This fixture exercises field access through two structurally distinct
// 3-level nestings simultaneously to assert they do not alias: the same
// compile unit creates and reads both &Option<Box<A>> and &Option<Box<B>>.
// Under the bug, the two struct hashes would collide after the ×256 wrap
// (different inner structs, same wrapped surrogate), so the field offsets
// would be wrong for at least one of them.

struct A { x: i64, y: i64 }
struct B { p: i64, q: i64, r: i64 }

fn read_a(slot: &Option<Box<A>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).x + (*n).y,
        None => 0 - 1,
    }
}

fn read_b(slot: &Option<Box<B>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).p + (*n).q + (*n).r,
        None => 0 - 1,
    }
}

fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    let ba = Box::new(A { x: 10, y: 20 })
    let ha: Option<Box<A>> = Some(ba)

    let bb = Box::new(B { p: 100, q: 200, r: 300 })
    let hb: Option<Box<B>> = Some(bb)

    let va = read_a(&ha)
    let vb = read_b(&hb)

    assert(va == 30)
    assert(vb == 600)

    // The deepest nesting: read across two distinct 3-level types in the
    // same translation unit. Pre-fix the hash collision would corrupt at
    // least one of the field reads; post-fix both decode cleanly.
    print("type-hash 3-level PASS\n")
    0
}

